<script setup lang="ts">import {computed} from 'vue';const props=defineProps<{title:string;value:number;total:number;detail?:string}>();const percent=computed(()=>props.total>0?Math.max(0,Math.min(100,props.value/props.total*100)):0);</script>
<template><article class="vx-dash-tile"><div class="vx-dash-label">{{title}}</div><div class="vx-dash-value">{{Math.round(percent)}}%</div><div class="vx-dash-track" role="progressbar" :aria-valuenow="value" :aria-valuemax="total" aria-valuemin="0" :aria-label="title"><span :style="{width:percent+'%'}"/></div><div class="vx-dash-sub">{{detail||`${value} of ${total}`}}</div></article></template>
